import requests

def get_user_messages(channel):
    response = requests.get(f'https://slack.com/api/conversations.history?channel={channel}&limit=1000')
    data = response.json()
    user_messages = {}
    for message in data['messages']:
        user = message['user']
        if user not in user_messages:
            user_messages[user] = 0
        user_messages[user] += 1
    return user_messages

def sort_users_by_messages(user_messages):
    sorted_users = sorted(user_messages.items(), key=lambda x: (-x[1], x[0]))
    return sorted_users

def send_message(user, rank):
    response = requests.post('https://slack.com/api/chat.postMessage', json={'channel': user, 'text': f'Congrats on being the {rank}-th most active user!'})
    return response.json()

def main():
    channels = ['general', 'random', 'private', 'External_0']
    user_messages = {}
    for channel in channels:
        messages = get_user_messages(channel)
        for user, count in messages.items():
            if user not in user_messages:
                user_messages[user] = 0
            user_messages[user] += count
    sorted_users = sort_users_by_messages(user_messages)
    for i, (user, _) in enumerate(sorted_users):
        send_message(user, i+1)

main()
